use super::*;
use crate::ledger::Transcript;
use serde_json::json;
fn ev(seq:u64,kind:&str,p:Value,s:i64)->Value {json!({"id":format!("e{seq}"),"sequence":seq,"runId":"run_1","missionId":"mission_1","sourceAdapter":"claude","occurredAt":chrono::DateTime::from_timestamp_millis(1_700_000_000_000+s*1000).unwrap().to_rfc3339(),"type":kind,"payload":p})}
fn start()->Value{ev(1,"run.started",json!({"runtimeThreadId":"t"}),0)}
fn done(seq:u64,s:i64)->Value{ev(seq,"run.completed",json!({"runtimeThreadId":"t","process":{}}),s)}
fn tool(seq:u64,id:&str,name:&str,command:&str,s:i64)->Vec<Value>{vec![ev(seq,"tool.started",json!({"itemId":id,"name":name,"command":command,"phase":"started"}),s),ev(seq+1,"tool.completed",json!({"itemId":id,"name":name,"command":command,"phase":"completed","exitCode":0}),s+1)]}
fn fold(events:&[Value])->Transcript {let mut t=Transcript::default();t.apply(events.iter().map(|e|json!({"recordType":"mission.event","event":e})).collect());t}
fn trace(events:&[Value],running:bool)->Trace{activity_trace(&fold(events).items,events,outcome(events,running))}
fn seg<'a>(t:&'a Trace,key:&str)->Option<&'a Segment>{t.segments.iter().find(|s|s.key==key)}
#[test] fn leads_with_the_duration_and_ends_with_the_exceptions_a_zero_segment_is_absent(){
    let events=vec![start(),ev(2,"step.started",json!({"stepKind":"reasoning","itemId":"r1"}),1),ev(3,"step.completed",json!({"stepKind":"reasoning","itemId":"r1"}),8),ev(4,"tool.started",json!({"itemId":"a","name":"Agent","command":"Count lines","phase":"started"}),9),ev(5,"tool.completed",json!({"itemId":"a","name":"Agent","command":"Count lines","phase":"completed","status":"Explore","output":"3"}),20),ev(6,"tool.started",json!({"itemId":"b","name":"Read","command":"README.md","phase":"started"}),21),ev(7,"tool.completed",json!({"itemId":"b","name":"Read","command":"README.md","phase":"completed"}),22),ev(8,"adapter.diagnostic",json!({"code":"claude.notification","level":"warning","terminal":false,"message":"Stop hook error occurred"}),40),done(9,41)];
    let t=trace(&events,false);assert_eq!(t.text(),"41s · thought 7s · asked 1 subagent · 1 tool call");assert!(seg(&t,"notices").is_none());assert_eq!(seg(&t,"subagents").unwrap().tone,None);
}
#[test] fn counts_the_commands_first_and_calls_the_rest_other_tool_calls(){
    let mut events=vec![start()];for (at,id,path) in [(2,"r1","LOCUST.md"),(4,"r2","README.md"),(6,"r3","batch")] {events.extend(tool(at,id,"read",path,at as i64));}for (at,id,cmd) in [(8,"s1","mkdir -p batch && printf 'a' > batch/a.txt"),(10,"s2","printf 'b' > batch/b.txt"),(12,"s3","printf 'c' > batch/c.txt")] {events.extend(tool(at,id,"bash",cmd,at as i64));}events.push(done(14,14));assert_eq!(trace(&events,false).text(),"14s · ran 3 commands: mkdir and printf · 3 other tool calls");
}
#[test] fn does_not_count_thinking_as_a_tool_call_on_the_line_a_person_reads(){
    let mut events=vec![start(),ev(2,"step.started",json!({"stepKind":"reasoning","itemId":"r1"}),1),ev(3,"step.completed",json!({"stepKind":"reasoning","itemId":"r1","message":"Need two reads, then answer."}),8)];events.extend(tool(4,"a","read","README.md",9));events.extend(tool(6,"b","read","package.json",11));events.push(done(8,13));assert!(fold(&events).items.iter().any(|i|matches!(i,Item::Thought{..})));assert_eq!(trace(&events,false).text(),"13s · thought 7s · 2 tool calls");
    let only=vec![start(),ev(2,"step.started",json!({"stepKind":"reasoning","itemId":"r1"}),1),ev(3,"step.completed",json!({"stepKind":"reasoning","itemId":"r1","message":"Just thinking."}),8),done(4,9)];assert!(!trace(&only,false).text().contains("tool call"));assert_eq!(crate::activity_summary::activity_summary(&fold(&only).items),"No tool activity");
}
#[test] fn names_the_one_command_it_ran_rather_than_counting_it(){
    let wrapped="\"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe\" -NoProfile -Command \"seq 1 300\"";
    let events=vec![start(),ev(2,"tool.started",json!({"itemId":"a","name":"shell","command":wrapped,"phase":"started"}),1),ev(3,"tool.completed",json!({"itemId":"a","name":"shell","command":wrapped,"phase":"completed","output":"1\n2\n3","exitCode":0}),12),done(4,12)];let t=trace(&events,false);let ran=seg(&t,"commands").unwrap();assert_eq!(ran.text,"ran seq 1 300");assert!(!ran.text.contains("powershell"));assert!(seg(&t,"calls").is_none());
}
#[test] fn says_the_one_command_is_running_while_it_has_no_result_not_that_it_ran_0_378(){
    let mut events=vec![start(),ev(2,"tool.started",json!({"itemId":"a","name":"shell","command":"echo hi","phase":"started"}),1)];assert_eq!(seg(&trace(&events,true),"commands").unwrap().text,"running echo hi");events.push(ev(3,"tool.completed",json!({"itemId":"a","name":"shell","command":"echo hi","phase":"completed","exitCode":0}),2));events.push(done(4,2));assert_eq!(seg(&trace(&events,false),"commands").unwrap().text,"ran echo hi");
}
#[test] fn counts_several_commands_and_says_how_they_came_out(){let mut events=vec![start()];events.extend(tool(2,"a","shell","ls",1));events.extend(tool(4,"b","shell","pwd",3));events.push(done(6,4));let t=trace(&events,false);assert_eq!(seg(&t,"commands").unwrap().text,"ran ls and pwd");assert!(seg(&t,"calls").is_none());}
#[test] fn carries_the_notices_it_used_to_only_count_as_sentences_on_the_fold(){let events=vec![start(),ev(2,"adapter.diagnostic",json!({"code":"codex.setup","level":"info","terminal":false,"message":"Skill descriptions were shortened."}),1),ev(3,"tool.started",json!({"itemId":"a","name":"Bash","command":"ls","phase":"started"}),2),ev(4,"tool.completed",json!({"itemId":"a","name":"Bash","command":"ls","phase":"completed","output":"README.md"}),3),done(5,4)];let t=trace(&events,false);assert_eq!(t.notices,[Notice{level:"info".into(),message:"Skill descriptions were shortened.".into(),source:"claude".into()}]);assert!(!fold(&events).items.iter().any(|i|matches!(i,Item::Note{..})));}
#[test] fn says_a_subagent_did_not_report_in_amber_only_once_the_turn_is_over(){let mut events=vec![start(),ev(2,"tool.started",json!({"itemId":"a","name":"Agent","command":"Search","phase":"started"}),1)];assert_eq!(trace(&events,true).text(),"1s · asked 1 subagent");events.push(ev(3,"run.cancelled",json!({"process":{}}),30));let t=trace(&events,false);assert_eq!(t.text(),"stopped at 30s · nothing was changed · asked 1 subagent · it did not report");assert_eq!(seg(&t,"subagents").unwrap().tone.as_deref(),Some("amber"));}
#[test] fn has_the_duration_as_its_floor_and_words_a_stop_honestly(){assert_eq!(activity_trace(&[],&[start(),done(2,275)],"completed").text(),"4m 35s");assert_eq!(crate::ledger::duration_text(3_960_000),"1h 06m");assert_eq!(outcome(&[ev(1,"run.failed",json!({"message":"x"}),0)],false),"failed");}
